parent_snippets.text:
    php: ${{ matrix.php }}
    theme: ${{ matrix.theme }}
    multisite: ${{ matrix.multisite }}
    coverage: ${{ matrix.coverage }}
    experimental: ${{ matrix.experimental || false }}
    install_wp_graphql_core_deps: true

# ===========================================
# WP GraphQL for ACF – matrix (full vs Free-only for fork PRs)
# ===========================================
# For PRs from forks, secrets (ACF_LICENSE_KEY, ACF_EXTENDED_LICENSE_KEY) are not
# available. We output only ACF Free / ACF Extended Free rows so fork PRs still run
# integration tests without needing Pro licenses.
# ===========================================

    SVN_PASSWORD: ${{ secrets.SVN_PASSWORD }}
    SVN_USERNAME: ${{ secrets.SVN_USERNAME }}
    # Use WordPress.org slug (not GitHub component name) for deployment
    # wp-graphql-smart-cache (component) -> wpgraphql-smart-cache (WordPress.org slug)
    SLUG: ${{ steps.plugin_info.outputs.wp_org_slug }}
    BUILD_DIR: plugin-build/${{ matrix.component }}
    VERSION: ${{ steps.plugin_info.outputs.version }}
    # Note: The 10up action should sync BUILD_DIR to SVN trunk
    # If it's not updating readme.txt, it might be reading from the source tag
    # We've updated BUILD_DIR/readme.txt, so it should sync correctly

- name: Verify and fix SVN trunk readme.txt if needed
  # The 10up action may not update readme.txt correctly, so we manually verify and fix it
  env:

  working-directory: websites/wpgraphql.com

- name: Build website
  run: npm run build -w @wpgraphql/wpgraphql-com
  env:
    NEXT_PUBLIC_SITE_URL: ${{ secrets.NEXT_PUBLIC_SITE_URL || 'https://www.wpgraphql.com' }}
    WPGRAPHQL_URL: ${{ secrets.WPGRAPHQL_URL }}
    NEXT_PUBLIC_WORDPRESS_URL: ${{ secrets.NEXT_PUBLIC_WORDPRESS_URL }}
    FAUSTWP_SECRET_KEY: ${{ secrets.FAUSTWP_SECRET_KEY }}

- name: Start production server
  run: |
    cd websites/wpgraphql.com
    npm run start > /tmp/nextjs.log 2>&1 &
    echo $! > /tmp/nextjs.pid

